('lib/content/gpx_scolarite/dps_dpg/generalite_pages/hierarchie_police/hierarchie_apj_page.dart','f00011','A. La qualité d’agent de police judiciaire',11,'_Paragraph','Ils doivent, en parallèle, seconder les officiers de police judiciaire dans l’accomplissement de leurs missions d’enquête.','Ils doivent, en parallèle, seconder les officiers de police judiciaire dans l’accomplissement de leurs missions d’enquête.','{}'::jsonb,true),
('lib/content/gpx_scolarite/dps_dpg/generalite_pages/hierarchie_police/hierarchie_apj_page.dart','f00012','A. La qualité d’agent de police judiciaire',12,'TextSpan','L’article 20 du code de procédure pénale définit une première catégorie d’agents de police judiciaire. ','L’article 20 du code de procédure pénale définit une première catégorie d’agents de police judiciaire. ','{}'::jsonb,true),
