('lib/content/gpx_scolarite/dps_dpg/generalite_pages/hierarchie_police/hierarchie_apj_page.dart','f00019','B. Les agents de police judiciaire de l’article 20 du code de procédure pénale',19,'TextSpan','Ces agents de police judiciaire participent aux missions d’enquête, exécutent les instructions des officiers de police judiciaire et réalisent les actes entrant dans leurs attributions, sous la direction de l’autorité judiciaire.','Ces agents de police judiciaire participent aux missions d’enquête, exécutent les instructions des officiers de police judiciaire et réalisent les actes entrant dans leurs attributions, sous la direction de l’autorité judiciaire.','{}'::jsonb,true),
('lib/content/gpx_scolarite/dps_dpg/generalite_pages/hierarchie_police/hierarchie_apj_page.dart','f00020','B.2 Conditions d’exercice de la qualité d’agent de police judiciaire (article 20)',20,'title','B.2 Conditions d’exercice de la qualité d’agent de police judiciaire (article 20)','B.2 Conditions d’exercice de la qualité d’agent de police judiciaire (article 20)','{}'::jsonb,true),
