('lib/content/gpx_scolarite/dps_dpg/generalite_pages/hierarchie_police/hierarchie_apj_page.dart','f00022','B.2 Conditions d’exercice de la qualité d’agent de police judiciaire (article 20)',22,'string','Ils doivent être affectés à un emploi comportant l’exercice de la police judiciaire.','Ils doivent être affectés à un emploi comportant l’exercice de la police judiciaire.','{}'::jsonb,true),
('lib/content/gpx_scolarite/dps_dpg/generalite_pages/hierarchie_police/hierarchie_apj_page.dart','f00023','B.2 Conditions d’exercice de la qualité d’agent de police judiciaire (article 20)',23,'string','Ils ne doivent pas participer, en unité constituée, à une opération de maintien de l’ordre.','Ils ne doivent pas participer, en unité constituée, à une opération de maintien de l’ordre.','{}'::jsonb,true),
